SELECT setval('public.users_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.users));
SELECT setval('public.categories_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.categories));
SELECT setval('public.products_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.products));
SELECT setval('public.orders_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.orders));
SELECT setval('public.order_items_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.order_items));